export function Button({
  label = "{{label}}",
  variant = "{{variant}}",
  disabled = {{disabled}},
}) {
  const base = {
    padding: "12px 20px",
    borderRadius: {{radius}},
    border: "2px solid {{bg}}",
    background: variant === "primary" ? "{{bg}}" : "transparent",
    color: variant === "primary" ? "#FAF7F2" : "{{bg}}",
    cursor: disabled ? "not-allowed" : "pointer",
    opacity: disabled ? 0.45 : 1,
  };
  return <button style={base} disabled={disabled}>{label}</button>;
}
